1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useGlobalStore } from '../../store/useGlobalStore';
3	import { GameLayout } from '../../components/GameLayout';
4	import { Sparkles, List, Sliders, Dna, Bot } from 'lucide-react';
5	
6	// Import styles for Black Hole physics and Gacha UI
7	import './styles/juraGlobal.css';
8	
9	// Import modular tab views (1 folder per tab architecture)
10	import { GachaTab } from './components/tabs/gacha/GachaTab';
11	import { DinoDetailsTab } from './components/tabs/details/DinoDetailsTab';
12	import { AllDinosTab } from './components/tabs/alldinos/AllDinosTab';
13	import { SettingsTab } from './components/tabs/settings/SettingsTab';
14	
15	import { useArcJurassicStore, type ResourceData } from './store/useArcJurassicStore';
16	export type { ResourceData };
17	import { calcUserTop3Ferocity, calcUserTotalFerocity, calcGachaPool, selectWeightedRoll } from './core/calcGachaPool';
18	import { calcDinoCost } from './core/calcDinoCost';
19	import { calcDinoMaxCapacity, calcDinoRank, calcDinosNeededForDinoNextEvo, calcDinosNeededForDinoMaxEvo } from './core/evolutionEngine';
20	import { rutGonTime } from './core/rutGonTime';
21	import {
22	  fetchArcProgress,
23	  persistArcProgress,
24	  resetArcProgress
25	} from '../../core/syncEngine';
26	import type { DueDinoData, BuyAnimationTarget } from './components/tabs/gacha/types';
27	
28	// Import raw game data directly for optimal Vite bundling and zero runtime fetch errors
29	import dinoRawData from './data/dino.json';
30	import lookupRawData from './data/lookup.json';
31	import userProgressRawData from './data/user_progress.json';
32	
33	// Complete data structures for Universe 25 integration
34	interface DinoObject {
35	  uuid: string;
36	  name: string;
37	  image_url: string;
38	  region: string;
39	  rarity: string;
40	  hybrid_type: string;
41	  class: string;
42	  hatch_time_mins: number;
43	  buy_price_dna: number;
44	  sell_price_dna: number;
45	  release_date: string;
46	  facts: string[];
47	  ingredients: any[];
48	  evolutions: {
49	    level: number;
50	    health: number;
51	    damage: number;
52	    image_url: string;
53	    portrait_frame: string;
54	  }[];
55	}
56	
57	interface LookupData {
58	  class_icons: Record<string, string>;
59	  card_backgrounds: Record<string, string>;
60	  hybrid_types: Record<string, string>;
61	  region: Record<string, string>;
62	  portrait_frames: Record<string, string>;
63	  stats: Record<string, string>;
64	}
65	
66	interface UserProgress {
67	  owned_dinos: Record<string, { number: number; rank: number; ferocity?: number }>;
68	}
69	
70	const LOCAL_STORAGE_CHEAT_KEY = 'arc_jurassic_free_buy_cheat_v1';
71	const LOCAL_STORAGE_RAPID_MODE_KEY = 'arc_jurassic_rapid_mode_v1';
72	const LOCAL_STORAGE_AUTO_GACHA_BUY_KEY = 'arc_jurassic_auto_gacha_buy_v1';
73	const LOCAL_STORAGE_DUE_DINO_KEY = 'arc_jurassic_due_dino_v1';
74	
75	export const ArcJurassic: React.FC = () => {
76	  const setActiveApp = useGlobalStore((s) => s.setActiveApp);
77	
78	  // State for game data
79	  const [objects, setObjects] = useState<DinoObject[]>([]);
80	  const [lookup, setLookup] = useState<LookupData>({
81	    class_icons: {},
82	    card_backgrounds: {},
83	    hybrid_types: {},
84	    region: {},
85	    portrait_frames: {},
86	    stats: {},
87	  });
88	  const [userProgress, setUserProgress] = useState<UserProgress>({ owned_dinos: {} });
89	  const myResources = useArcJurassicStore((s) => s.resources);
90	  const setMyResources = useArcJurassicStore((s) => s.setResources);
91	  const hydrateArcResources = useArcJurassicStore((s) => s.hydrateFromBackend);
92	  const [loading, setLoading] = useState(true);
93	  const [view, setView] = useState<'gacha' | 'alldinos' | 'settings'>('gacha');
94	  const [rosterTargetUuid, setRosterTargetUuid] = useState<string | null>(null);
95	  const [buyAnimationTarget, setBuyAnimationTarget] = useState<BuyAnimationTarget | null>(null);
96	
97	  // Due Dino persistence: lightweight frontend state (remembers unbought roll)
98	  const [dueDino, setDueDino] = useState<DueDinoData | null>(() => {
99	    try {
100	      const saved = localStorage.getItem(LOCAL_STORAGE_DUE_DINO_KEY);
101	      return saved ? JSON.parse(saved) : null;
102	    } catch {
103	      return null;
104	    }
105	  });
106	
107	  const [excludedIds, setExcludedIds] = useState<string[]>([]);
108	  const [top3Ferocity, setTop3Ferocity] = useState(0);
109	  const [totalArmyFerocity, setTotalArmyFerocity] = useState(0);
110	  const [isFreeBuyCheat, setIsFreeBuyCheat] = useState<boolean>(() => {
111	    try {
112	      return localStorage.getItem(LOCAL_STORAGE_CHEAT_KEY) === 'true';
113	    } catch {
114	      return false;
115	    }
116	  });
117	  const [isRapidMode, setIsRapidMode] = useState<boolean>(() => {
118	    try {
119	      return localStorage.getItem(LOCAL_STORAGE_RAPID_MODE_KEY) === 'true';
120	    } catch {
121	      return false;
122	    }
123	  });
124	  const [isAutoGachaBuy, setIsAutoGachaBuy] = useState<boolean>(() => {
125	    try {
126	      return localStorage.getItem(LOCAL_STORAGE_AUTO_GACHA_BUY_KEY) === 'true';
127	    } catch {
128	      return false;
129	    }
130	  });
131	
132	  // Auto Gacha & Buy 10-Roll Cap Limiter
133	  const AUTO_GACHA_ROLL_CAP = 10;
134	  const [autoRollsRemaining, setAutoRollsRemaining] = useState<number>(AUTO_GACHA_ROLL_CAP);
135	  const autoRollsRemainingRef = useRef<number>(AUTO_GACHA_ROLL_CAP);
136	  autoRollsRemainingRef.current = autoRollsRemaining;
137	
138	  // Load game data from authoritative backend SQLite tiers with bundled fallback
139	  useEffect(() => {
140	    const initGameData = async () => {
141	      try {
142	        // 1. Process Dino Objects
143	        const dinoObjects: DinoObject[] = Object.entries(dinoRawData).map(([uuid, dino]) => ({
144	          uuid,
145	          ...(dino as Omit<DinoObject, 'uuid'>)
146	        }));
147	
148	        // 2. Authoritative Backend SQLite Progress Hydration
149	        let initialProgress: UserProgress = userProgressRawData as UserProgress;
150	        try {
151	          const backendProgress = await fetchArcProgress();
152	          if (backendProgress && Object.keys(backendProgress.owned_dinos || {}).length > 0) {
153	            initialProgress = backendProgress as UserProgress;
154	          } else {
155	            await persistArcProgress(initialProgress as any);
156	          }
157	        } catch (err) {
158	          console.warn('[ARC Jurassic] Backend SQLite progress hydration notice:', err);
159	        }
160	
161	        // 3. Authoritative Backend SQLite Resources Hydration via Shared Store
162	        await hydrateArcResources();
163	
164	        setObjects(dinoObjects);
165	        setLookup(lookupRawData as unknown as LookupData);
166	        setUserProgress(initialProgress);
167	
168	        // 4. Calculate top 3 ferocity stats & excluded IDs
169	        const calculatedExcludedIds: string[] = [];
170	
171	        for (const [uuid, data] of Object.entries(initialProgress.owned_dinos || {})) {
172	          const dino = dinoObjects.find((d: DinoObject) => (d.uuid || (d as any).id || (d as any).name) === uuid);
173	          if (dino) {
174	            const limit = calcDinoMaxCapacity(dino);
175	            if ((data as any).number >= limit) {
176	              calculatedExcludedIds.push(uuid);
177	            }
178	          }
179	        }
180	
181	        const top3 = calcUserTop3Ferocity(dinoObjects, initialProgress);
182	        const totalFero = calcUserTotalFerocity(dinoObjects, initialProgress);
183	
184	        setExcludedIds(calculatedExcludedIds);
185	        setTop3Ferocity(top3);
186	        setTotalArmyFerocity(totalFero);
187	        setLoading(false);
188	      } catch (error) {
189	        console.error("Error initializing ARC Jurassic game data:", error);
190	        setLoading(false);
191	      }
192	    };
193	
194	    initGameData();
195	  }, []);
196	
197	  const handleUpdateProgress = async (prog: UserProgress) => {
198	    setUserProgress(prog);
199	    const totalFero = calcUserTotalFerocity(objects, prog);
200	    const top3 = calcUserTop3Ferocity(objects, prog);
201	    setTotalArmyFerocity(totalFero);
202	    setTop3Ferocity(top3);
203	
204	    // Recalculate excluded IDs for creatures reaching max capacity
205	    const calculatedExcludedIds: string[] = [];
206	    for (const [uuid, data] of Object.entries(prog.owned_dinos || {})) {
207	      const dino = objects.find((d: DinoObject) => (d.uuid || (d as any).id || (d as any).name) === uuid);
208	      if (dino) {
209	        const limit = calcDinoMaxCapacity(dino);
210	        if ((data as any).number >= limit) {
211	          calculatedExcludedIds.push(uuid);
212	        }
213	      }
214	    }
215	    setExcludedIds(calculatedExcludedIds);
216	
217	    try {
218	      await persistArcProgress(prog as any);
219	    } catch (e) {
220	      console.warn('Failed to save progress to SQLite backend:', e);
221	    }
222	  };
223	
224	  const handleResetCollection = async () => {
225	    setUserProgress({ owned_dinos: {} });
226	    setTotalArmyFerocity(0);
227	    setTop3Ferocity(0);
228	    setExcludedIds([]);
229	    try {
230	      await resetArcProgress();
231	    } catch (e) {
232	      console.warn('Failed to reset progress in SQLite backend:', e);
233	    }
234	  };
235	
236	  const handleUpdateResources = (res: ResourceData) => {
237	    setMyResources(res);
238	  };
239	
240	  const handleSetDueDino = (data: DueDinoData | null) => {
241	    setDueDino(data);
242	    try {
243	      if (data) {
244	        localStorage.setItem(LOCAL_STORAGE_DUE_DINO_KEY, JSON.stringify(data));
245	      } else {
246	        localStorage.removeItem(LOCAL_STORAGE_DUE_DINO_KEY);
247	      }
248	    } catch (e) {
249	      console.warn('Failed to save due dino to localStorage:', e);
250	    }
251	  };
252	
253	  const handleToggleFreeBuyCheat = (enabled: boolean) => {
254	    setIsFreeBuyCheat(enabled);
255	    try {
256	      localStorage.setItem(LOCAL_STORAGE_CHEAT_KEY, String(enabled));
257	    } catch (e) {
258	      console.warn('Failed to save cheat state to localStorage:', e);
259	    }
260	  };
261	
262	  const handleToggleRapidMode = (enabled: boolean) => {
263	    setIsRapidMode(enabled);
264	    try {
265	      localStorage.setItem(LOCAL_STORAGE_RAPID_MODE_KEY, String(enabled));
266	    } catch (e) {
267	      console.warn('Failed to save rapid mode state to localStorage:', e);
268	    }
269	  };
270	
271	  const handleToggleAutoGachaBuy = (enabled: boolean) => {
272	    setIsAutoGachaBuy(enabled);
273	    if (enabled) {
274	      setAutoRollsRemaining(AUTO_GACHA_ROLL_CAP);
275	      autoRollsRemainingRef.current = AUTO_GACHA_ROLL_CAP;
276	    }
277	    try {
278	      localStorage.setItem(LOCAL_STORAGE_AUTO_GACHA_BUY_KEY, String(enabled));
279	    } catch (e) {
280	      console.warn('Failed to save auto gacha buy state to localStorage:', e);
281	    }
282	  };
283	
284	  // Autonomous Headless Auto Gacha & Auto Buy Controller
285	  // Operates continuously across any tab (including List of Dinos) without requiring Gacha Tab to be mounted
286	  useEffect(() => {
287	    if (!isAutoGachaBuy || loading || buyAnimationTarget !== null || rosterTargetUuid !== null) return;
288	    if (objects.length === 0) return;
289	
290	    let timer: ReturnType<typeof setTimeout>;
291	
292	    const executeAutonomousStep = () => {
293	      // 1. Calculate outcomes pool
294	      const poolResult = calcGachaPool(objects, userProgress, excludedIds);
295	      const possibleOutcomes = poolResult.pool;
296	      if (possibleOutcomes.length === 0) return;
297	
298	      // 2. Resolve Target Dino & Multiplier (check outstanding due dino first, else roll)
299	      let targetUuid: string | null = dueDino?.uuid || null;
300	      let multiplier: number = dueDino?.multiplier || 1;
301	
302	      if (!targetUuid) {
303	        // Read persisted wager
304	        let wagerOption: string | number = 1;
305	        try {
306	          const saved = localStorage.getItem('arc_jurassic_roll_wager_v1');
307	          if (saved === 'next-evo' || saved === 'max-evo') {
308	            wagerOption = saved;
309	          } else {
310	            const parsed = Number(saved);
311	            wagerOption = [1, 2, 3, 4, 8, 16].includes(parsed) ? parsed : 1;
312	          }
313	        } catch {
314	          wagerOption = 1;
315	        }
316	
317	        const roll = selectWeightedRoll(possibleOutcomes);
318	        if (!roll) return;
319	        targetUuid = roll.uuid;
320	
321	        const dinoObj = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
322	        if (wagerOption === 'next-evo') {
323	          multiplier = calcDinosNeededForDinoNextEvo(dinoObj || roll, userProgress);
324	        } else if (wagerOption === 'max-evo') {
325	          multiplier = calcDinosNeededForDinoMaxEvo(dinoObj || roll, userProgress);
326	        } else {
327	          const num = typeof wagerOption === 'number' ? wagerOption : Number(wagerOption);
328	          multiplier = isNaN(num) || num < 1 ? 1 : num;
329	        }
330	      }
331	
332	      const dino = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
333	      if (!dino) return;
334	
335	      // 3. Affordability & Capacity Check
336	      const cost = calcDinoCost(dino);
337	      const currentData = userProgress?.owned_dinos?.[targetUuid] || { number: 0, rank: 0 };
338	      const currentCount = Number((currentData as any).number || 0);
339	      const maxCapacity = calcDinoMaxCapacity(dino);
340	      const maxBuyable = Math.max(1, maxCapacity - currentCount);
341	      const buyQty = Math.min(Math.max(1, multiplier), maxBuyable);
342	
343	      const totalTimeSeconds = cost.totalTimeSeconds * buyQty;
344	
345	      let canAfford = isFreeBuyCheat;
346	      if (!canAfford) {
347	        const currentJurassicTime = Number(myResources.jurassic_time?.amount ?? myResources.elemental_time?.golden?.amount ?? 0);
348	        canAfford = currentJurassicTime >= totalTimeSeconds;
349	      }
350	
351	      if (!canAfford) {
352	        // If cannot afford, save as due dino if not already set, and wait for resources
353	        if (!dueDino) {
354	          handleSetDueDino({
355	            uuid: targetUuid,
356	            multiplier
357	          });
358	        }
359	        return;
360	      }
361	
362	      // 4. Deduct resources if cheat disabled
363	      if (!isFreeBuyCheat) {
364	        const newRes = { ...myResources };
365	        const currentJurassicTime = Number(newRes.jurassic_time?.amount ?? newRes.elemental_time?.golden?.amount ?? 0);
366	
367	        newRes.jurassic_time = {
368	          ...newRes.jurassic_time,
369	          amount: Math.max(0, Number((currentJurassicTime - totalTimeSeconds).toFixed(2)))
370	        };
371	
372	        handleUpdateResources(newRes);
373	      }
374	
375	      // 5. Calculate pool differential and extract target pool drop rate
376	      const prevPoolResult = calcGachaPool(objects, userProgress, excludedIds);
377	      const prevPoolSet = new Set(prevPoolResult.pool.map(p => p.uuid));
378	      const prevCap = prevPoolResult.cap;
379	      const targetPoolDino = prevPoolResult.pool.find(p => p.uuid === targetUuid);
380	      const dropRatePercent = targetPoolDino ? targetPoolDino.dropRatePercent : undefined;
381	
382	      // 6. Update progress & rank
383	      const newProg = { ...userProgress, owned_dinos: { ...(userProgress?.owned_dinos || {}) } };
384	      const updatedCount = currentCount + buyQty;
385	      const evoCount = dino.evolutions?.length || 4;
386	      const prevRank = calcDinoRank(currentCount, evoCount);
387	      const newRank = calcDinoRank(updatedCount, evoCount);
388	      const wasFirstBuy = currentCount === 0;
389	
390	      newProg.owned_dinos[targetUuid] = {
391	        number: updatedCount,
392	        rank: newRank
393	      };
394	
395	      handleUpdateProgress(newProg);
396	
397	      // Post-progress pool
398	      const postPoolResult = calcGachaPool(objects, newProg, excludedIds);
399	      const newCap = postPoolResult.cap;
400	      const newlyUnlockedPoolDinos = postPoolResult.pool.filter(p => !prevPoolSet.has(p.uuid));
401	
402	      // Clear due dino on successful purchase
403	      if (dueDino) {
404	        handleSetDueDino(null);
405	      }
406	
407	      // 7. Trigger Rank Climb animation directly on active view
408	      setBuyAnimationTarget({
409	        uuid: targetUuid,
410	        wasFirstBuy,
411	        prevRank,
412	        newRank,
413	        buyQty,
414	        dropRatePercent,
415	        newlyUnlockedPoolDinos,
416	        prevCap,
417	        newCap
418	      });
419	
420	      // 8. Decrement remaining auto rolls (shutdown will be triggered AFTER up-evo / rank climb finishes)
421	      const nextRolls = Math.max(0, autoRollsRemainingRef.current - 1);
422	      autoRollsRemainingRef.current = nextRolls;
423	      setAutoRollsRemaining(nextRolls);
424	
425	      // Ensure view is on List of Dinos so the user experiences the rank climb animation
426	      if (view !== 'alldinos') {
427	        setView('alldinos');
428	      }
429	    };
430	
431	    timer = setTimeout(executeAutonomousStep, 600);
432	
433	    return () => {
434	      if (timer) clearTimeout(timer);
435	    };
436	  }, [
437	    isAutoGachaBuy,
438	    loading,
439	    buyAnimationTarget,
440	    rosterTargetUuid,
441	    objects,
442	    userProgress,
443	    excludedIds,
444	    dueDino,
445	    isFreeBuyCheat,
446	    myResources,
447	    view
448	  ]);
449	
450	  const handleClearAnimation = useCallback(() => {
451	    setBuyAnimationTarget(null);
452	    // Disarm Auto Gacha & Buy AFTER the rank climb / up-evo sequence has completely finished
453	    if (autoRollsRemainingRef.current <= 0) {
454	      setIsAutoGachaBuy(false);
455	      try {
456	        localStorage.setItem(LOCAL_STORAGE_AUTO_GACHA_BUY_KEY, 'false');
457	      } catch (e) {
458	        console.warn('Failed to save auto gacha buy state to localStorage:', e);
459	      }
460	    }
461	  }, []);
462	
463	  const handleReturnToGacha = useCallback(() => {
464	    setView('gacha');
465	  }, []);
466	
467	  const handleBuySuccess = useCallback((summary: BuyAnimationTarget) => {
468	    setBuyAnimationTarget(summary);
469	    setView('alldinos');
470	  }, []);
471	
472	  const handleOpenDinoDetails = useCallback((uuid: string | null) => {
473	    // Opening the Dino Details sidebar immediately disarms Auto Gacha & Buy mode
474	    if (uuid) {
475	      setIsAutoGachaBuy(prev => {
476	        if (prev) {
477	          try {
478	            localStorage.setItem(LOCAL_STORAGE_AUTO_GACHA_BUY_KEY, 'false');
479	          } catch (e) {
480	            console.warn('Failed to save auto gacha buy state to localStorage:', e);
481	          }
482	          return false;
483	        }
484	        return prev;
485	      });
486	    }
487	    setRosterTargetUuid(uuid);
488	  }, []);
489	
490	  // Handle navigation back to master game
491	  const handleBackToHub = () => {
492	    setActiveApp('golden-hour');
493	  };
494	
495	  if (loading) {
496	    return (
497	      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-900 text-white">
498	        <div className="text-4xl mb-6">⏳ Loading ARC Jurassic...</div>
499	        <div className="animate-spin rounded-full border-4 border-b-4 border-amber-500 w-16 h-16"></div>
500	      </div>
501	    );
502	  }
503	
504	  return (
505	    <GameLayout
506	      title="ARC Jurassic"
507	      gameTitleIcon={<Dna className="w-5 h-5 text-[#ffd86b]" />}
508	      gameTitleBadge="GENETIC VAULT"
509	      gameTitleSubtitle="Prehistoric Gacha Nexus • DNA Synthesis Lab"
510	      showBackButton={true}
511	      backButton="Golden Hour"
512	      onBackClick={handleBackToHub}
513	      headerRight={
514	        <div className="flex items-center gap-3 text-xs font-mono flex-wrap">
515	          {/* Total Army Ferocity Indicator */}
516	          <div className="flex items-center gap-2 bg-[#161208] px-3.5 py-1.5 rounded-xl border border-amber-500/50 text-xs font-mono font-bold text-amber-300 shadow-[0_0_12px_rgba(255,215,0,0.18)]">
517	            <img
518	              src="https://cdn.paleo.gg/games/jwtg/images/stats/ferocity.png"
519	              className="w-4 h-4 object-contain"
520	              alt="Ferocity"
521	            />
522	            <span>{totalArmyFerocity.toLocaleString()} Total Fero</span>
523	          </div>
524	
525	          {/* Dedicated Resource 1: Jurassic Time */}
526	          <div className="flex items-center gap-2 bg-[#14101c] px-3.5 py-1.5 rounded-xl border border-[#2e2638] text-xs font-mono font-bold text-sky-400 shadow-sm">
527	            <img src={myResources.jurassic_time?.icon} className="w-4 h-4 object-contain" alt="Jurassic Time" />
528	            <span>{rutGonTime(myResources.jurassic_time?.amount || 0, "seconds")}</span>
529	          </div>
530	
531	          {/* Dedicated Resource 2: DNA */}
532	          <div className="flex items-center gap-2 bg-[#14101c] px-3.5 py-1.5 rounded-xl border border-[#2e2638] text-xs font-mono font-bold text-[#ffd86b] shadow-sm">
533	            <img src={myResources.dna?.icon} className="w-4 h-4 object-contain" alt="DNA" />
534	            <span>{(myResources.dna?.amount || 0).toLocaleString()} DNA</span>
535	          </div>
536	
537	          {/* Dedicated Resource 3: Red Orbs */}
538	          <div className="flex items-center gap-2 bg-[#1c1424] px-3.5 py-1.5 rounded-xl border border-rose-900/60 text-xs font-mono font-bold text-rose-400 shadow-sm">
539	            <img src={myResources.red_orbs?.icon} className="w-4 h-4 object-contain" alt="Red Orbs" />
540	            <span>{myResources.red_orbs?.amount || 0} Orbs</span>
541	          </div>
542	
543	          {/* Quick Control: Auto Gacha & Buy Master Killswitch */}
544	          <button
545	            type="button"
546	            onClick={() => handleToggleAutoGachaBuy(!isAutoGachaBuy)}
547	            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl border text-xs font-mono font-bold transition-all cursor-pointer select-none ${
548	              isAutoGachaBuy
549	                ? 'bg-emerald-950/80 hover:bg-rose-950/80 border-emerald-400 hover:border-rose-400 text-emerald-300 hover:text-rose-300 shadow-[0_0_12px_rgba(52,211,153,0.35)] animate-pulse'
550	                : 'bg-[#14101c] hover:bg-[#20182c] border-[#2e2638] hover:border-emerald-500/50 text-[#8c7a9e] hover:text-emerald-400 shadow-sm'
551	            }`}
552	            title={isAutoGachaBuy ? 'Click to Stop Auto Gacha & Buy' : 'Click to Enable Auto Gacha & Buy (10-Roll Cap)'}
553	          >
554	            <Bot className={`w-4 h-4 ${isAutoGachaBuy ? 'text-emerald-400' : 'text-[#8c7a9e]'}`} />
