285	  // Autonomous Headless Auto Gacha & Auto Buy Controller
286	  // Operates continuously across any tab (including List of Dinos) without requiring Gacha Tab to be mounted
287	  useEffect(() => {
288	    if (!isAutoGachaBuy || loading || buyAnimationTarget !== null || rosterTargetUuid !== null) return;
289	    if (objects.length === 0) return;
290	
291	    let timer: ReturnType<typeof setTimeout>;
292	
293	    const executeAutonomousStep = () => {
294	      // 1. Calculate outcomes pool
295	      const poolResult = calcGachaPool(objects, userProgress, excludedIds);
296	      const possibleOutcomes = poolResult.pool;
297	      if (possibleOutcomes.length === 0) return;
298	
299	      // 2. Resolve Target Dino & Multiplier (check outstanding due dino first, else roll)
300	      let targetUuid: string | null = dueDino?.uuid || null;
301	      let multiplier: number = dueDino?.multiplier || 1;
302	
303	      if (!targetUuid) {
304	        // Read persisted wager
305	        let wagerOption: string | number = 1;
306	        try {
307	          const saved = localStorage.getItem('arc_jurassic_roll_wager_v1');
308	          if (saved === 'next-evo' || saved === 'max-evo') {
309	            wagerOption = saved;
310	          } else {
311	            const parsed = Number(saved);
312	            wagerOption = [1, 2, 3, 4, 8, 16].includes(parsed) ? parsed : 1;
313	          }
314	        } catch {
315	          wagerOption = 1;
316	        }
317	
318	        const roll = selectWeightedRoll(possibleOutcomes);
319	        if (!roll) return;
320	        targetUuid = roll.uuid;
321	
322	        const dinoObj = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
323	        if (wagerOption === 'next-evo') {
324	          multiplier = calcDinosNeededForDinoNextEvo(dinoObj || roll, userProgress);
325	        } else if (wagerOption === 'max-evo') {
326	          multiplier = calcDinosNeededForDinoMaxEvo(dinoObj || roll, userProgress);
327	        } else {
328	          const num = typeof wagerOption === 'number' ? wagerOption : Number(wagerOption);
329	          multiplier = isNaN(num) || num < 1 ? 1 : num;
330	        }
331	      }
332	
333	      const dino = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
334	      if (!dino) return;
335	
336	      // 3. Affordability & Capacity Check
337	      const cost = calcDinoCost(dino);
338	      const currentData = userProgress?.owned_dinos?.[targetUuid] || { number: 0, rank: 0 };
339	      const currentCount = Number((currentData as any).number || 0);
340	      const maxCapacity = calcDinoMaxCapacity(dino);
341	      const maxBuyable = Math.max(1, maxCapacity - currentCount);
342	      const buyQty = Math.min(Math.max(1, multiplier), maxBuyable);
343	
344	      const totalTimeSeconds = cost.totalTimeSeconds * buyQty;
345	
346	      let canAfford = isFreeBuyCheat;
347	      if (!canAfford) {
348	        const currentJurassicTime = Number(myResources.jurassic_time?.amount ?? myResources.elemental_time?.golden?.amount ?? 0);
349	        canAfford = currentJurassicTime >= totalTimeSeconds;
350	      }
351	
352	      if (!canAfford) {
353	        // If cannot afford, save as due dino if not already set, and wait for resources
354	        if (!dueDino) {
355	          handleSetDueDino({
356	            uuid: targetUuid,
357	            multiplier
358	          });
359	        }
360	        return;
361	      }
362	
363	      // 4. Deduct resources if cheat disabled
364	      if (!isFreeBuyCheat) {
365	        const newRes = { ...myResources };
366	        const currentJurassicTime = Number(newRes.jurassic_time?.amount ?? newRes.elemental_time?.golden?.amount ?? 0);
367	
368	        newRes.jurassic_time = {
369	          ...newRes.jurassic_time,
370	          amount: Math.max(0, Number((currentJurassicTime - totalTimeSeconds).toFixed(2)))
371	        };
372	
373	        handleUpdateResources(newRes);
374	      }
375	
376	      // 5. Calculate pool differential and extract target pool drop rate
377	      const prevPoolResult = calcGachaPool(objects, userProgress, excludedIds);
378	      const prevPoolSet = new Set(prevPoolResult.pool.map(p => p.uuid));
379	      const prevCap = prevPoolResult.cap;
380	      const targetPoolDino = prevPoolResult.pool.find(p => p.uuid === targetUuid);
381	      const dropRatePercent = targetPoolDino ? targetPoolDino.dropRatePercent : undefined;
382	
383	      // 6. Update progress & rank
384	      const newProg = { ...userProgress, owned_dinos: { ...(userProgress?.owned_dinos || {}) } };
385	      const updatedCount = currentCount + buyQty;
386	      const evoCount = dino.evolutions?.length || 4;
387	      const prevRank = calcDinoRank(currentCount, evoCount);
388	      const newRank = calcDinoRank(updatedCount, evoCount);
389	      const wasFirstBuy = currentCount === 0;
390	
391	      newProg.owned_dinos[targetUuid] = {
392	        number: updatedCount,
393	        rank: newRank
394	      };
395	
396	      handleUpdateProgress(newProg);
397	
398	      // Post-progress pool
399	      const postPoolResult = calcGachaPool(objects, newProg, excludedIds);
400	      const newCap = postPoolResult.cap;
401	      const newlyUnlockedPoolDinos = postPoolResult.pool.filter(p => !prevPoolSet.has(p.uuid));
402	
403	      // Clear due dino on successful purchase
404	      if (dueDino) {
405	        handleSetDueDino(null);
406	      }
407	
408	      // 7. Trigger Rank Climb animation directly on active view
409	      setBuyAnimationTarget({
410	        uuid: targetUuid,
411	        wasFirstBuy,
412	        prevRank,
413	        newRank,
