1	// path: src/apps/arc-jurassic/core/calcGachaPool.ts
2	// Pure Mathematical Engine for Gacha Pool Gating, Ingredient Inflation, True Inverse Ferocity Drop Rates, Top 3 Dinos, Total Army Ferocity, and Next Cap Milestones
3	
4	import { calcDinoCost, type DinoCostResult } from './calcDinoCost';
5	import { calcDinoMaxCapacity, calcDinoRank, getDinoAvatarUrl } from './evolutionEngine';
6	
7	export interface PoolDino {
8	    uuid: string;
9	    name: string;
10	    rarity: string;
11	    class?: string;
12	    hybrid_type?: string;
13	    ferocity: number; // Base evo4 ferocity
14	    modifiedFerocity: number; // For compatibility
15	    hybridMultiplier?: number; // Ingredient scaling multiplier (owned_materials / 10)
16	    isPartnerUnlock?: boolean; // Unlocked by owning a partner ingredient, bypassing cap
17	    isHybridBypass?: boolean; // Hybrid unlocked by owning its material ingredients, bypassing cap
18	    dropRatePercent: number; // Dynamic calculated drop probability (%)
19	    rawWeight: number; // Internal normalized inverse weight
20	    maxDamage: number;
21	    maxHealth: number;
22	    maxEvoImg: string;
23	    evo1Img: string;
24	    isOwned: boolean;
25	    ownedCount: number;
26	    currentRank: number;
27	    maximumNumber: number;
28	    image_url?: string;
29	    hatch_time_mins?: number;
30	    buy_price_dna?: number;
31	    sell_price_dna?: number;
32	    ingredients: string[];
33	    ownedIngredientsCount: number;
34	    totalIngredientsCount: number;
35	    cost: DinoCostResult;
36	}
37	
38	export interface TopDinoInfo {
39	    uuid: string;
40	    name: string;
41	    rarity: string;
42	    class?: string;
43	    rank: number;
44	    level: number;
45	    ownedCount: number;
46	    ferocity: number;
47	    damage: number;
48	    health: number;
49	    evoImg: string;
50	    image_url?: string;
51	}
52	
53	export interface NextUnlockMilestone {
54	    uuid: string;
55	    name: string;
56	    rarity: string;
57	    class?: string;
58	    image_url?: string;
59	    requiredFerocity: number;
60	    deltaNeeded: number;
61	}
62	
63	export interface GachaPoolResult {
64	    pool: PoolDino[];
65	    cap: number;
66	    top3Ferocity: number;
67	    totalAllFerocity: number;
68	    top3Dinos: TopDinoInfo[];
69	    topDinos: TopDinoInfo[];
70	    nextUnlock: NextUnlockMilestone | null;
71	    totalModifiedFerocity: number;
72	    excludedIds: string[];
73	}
74	
75	/**
76	 * Retrieves full data on the user's top highest-ferocity active dinos (up to limit, default 25).
77	 */
78	export function getUserTopDinos(objects: any[], userProgress: any, limit: number = 25): TopDinoInfo[] {
79	    const ownedDinos = userProgress?.owned_dinos || {};
80	    const list: TopDinoInfo[] = [];
81	
82	    for (const [uuid, data] of Object.entries(ownedDinos)) {
83	        const ownedData = data as { number?: number; rank?: number; ferocity?: number };
84	        const number = Number(ownedData.number || 0);
85	
86	        if (number > 0) {
87	            const dino = objects.find((d: any) => (d.uuid || d.id || d.name) === uuid);
88	            if (dino && dino.evolutions?.length > 0) {
89	                const rank = calcDinoRank(number, dino.evolutions.length);
90	                if (rank > 0) {
91	                    const activeIndex = Math.min(rank - 1, dino.evolutions.length - 1);
92	                    const evo = dino.evolutions[activeIndex];
93	                    if (evo) {
94	                        const fero = evo.ferocity !== undefined
95	                            ? Number(evo.ferocity)
96	                            : Math.floor(Number(evo.damage || 0) + (Number(evo.health || 0) / 3.2));
97	                        const targetLevel = Number(evo.level || rank * 10);
98	                        list.push({
99	                            uuid,
100	                            name: dino.name || '',
101	                            rarity: String(dino.rarity || '').toLowerCase(),
102	                            class: dino.class,
103	                            rank,
104	                            level: targetLevel,
105	                            ownedCount: number,
106	                            ferocity: fero,
107	                            damage: Number(evo.damage || 0),
108	                            health: Number(evo.health || 0),
109	                            evoImg: getDinoAvatarUrl(dino, rank, false),
110	                            image_url: dino.image_url,
111	                        });
112	                    }
113	                }
114	            }
115	        }
116	    }
117	
118	    list.sort((a, b) => b.ferocity - a.ferocity || a.name.localeCompare(b.name));
119	    return list.slice(0, limit);
120	}
121	
122	/**
123	 * Retrieves full data on the user's top 3 highest-ferocity active dinos.
124	 */
125	export function getUserTop3Dinos(objects: any[], userProgress: any): TopDinoInfo[] {
126	    return getUserTopDinos(objects, userProgress, 3);
127	}
128	
129	/**
130	 * Calculates user's top 3 ferocity sum based on highest active evolutions of owned creatures.
131	 */
132	export function calcUserTop3Ferocity(objects: any[], userProgress: any): number {
133	    const top3 = getUserTop3Dinos(objects, userProgress);
134	    return top3.reduce((sum, d) => sum + d.ferocity, 0);
135	}
136	
137	/**
138	 * Calculates user's total cumulative ferocity across ALL owned dinosaurs at their active unlocked levels.
139	 */
140	export function calcUserTotalFerocity(objects: any[], userProgress: any): number {
141	    const ownedDinos = userProgress?.owned_dinos || {};
142	    let total = 0;
143	
144	    for (const [uuid, data] of Object.entries(ownedDinos)) {
145	        const ownedData = data as { number?: number; rank?: number; ferocity?: number };
146	        const number = Number(ownedData.number || 0);
147	
148	        if (number > 0) {
149	            const dino = objects.find((d: any) => (d.uuid || d.id || d.name) === uuid);
150	            if (dino && dino.evolutions?.length > 0) {
151	                const rank = calcDinoRank(number, dino.evolutions.length);
152	                if (rank > 0) {
153	                    const activeIndex = Math.min(rank - 1, dino.evolutions.length - 1);
154	                    const evo = dino.evolutions[activeIndex];
155	                    if (evo) {
156	                        const fero = evo.ferocity !== undefined
157	                            ? Number(evo.ferocity)
158	                            : Math.floor(Number(evo.damage || 0) + (Number(evo.health || 0) / 3.2));
159	                        total += fero;
160	                    }
161	                }
162	            }
163	        }
164	    }
165	
166	    return total;
167	}
168	
169	/**
170	 * Main Gacha Pool Generator:
171	 * 1. Gates creatures by evo4_ferocity <= cap, where cap = max(floor(top3Ferocity / 2.5), 200).
172	 * 2. Excludes creatures that reached maximum_number.
173	 * 3. Applies ingredient scaling: hybrid_weight = normal_weight * (materials / 10).
174	 * 4. Partner & Hybrid bypass: Partner ingredient dinosaurs and Hybrids with owned materials bypass the cap.
175	 * 5. Calculates true inverse ferocity drop rates: w_i = 1 / ferocity (least ferocity -> highest drop rate).
176	 * 6. Finds the Next Unlock Milestone (the creature with lowest ferocity just above cap).
177	 * 7. Computes Top 3 Vanguards and Total Army Ferocity.
178	 */
179	export function calcGachaPool(
180	    objects: any[],
181	    userProgress: any,
182	    manualExcludedIds: string[] = []
183	): GachaPoolResult {
184	    const topDinos = getUserTopDinos(objects, userProgress, 25);
185	    const top3Dinos = topDinos.slice(0, 3);
186	    const top3Ferocity = top3Dinos.reduce((sum, d) => sum + d.ferocity, 0);
187	    const totalAllFerocity = calcUserTotalFerocity(objects, userProgress);
188	    // Cap is top 3 ferocity divided by 2.5, with minimum baseline floor of 200
189	    const cap = Math.max(Math.floor(top3Ferocity / 2.5), 200);
190	    const ownedDinos = userProgress?.owned_dinos || {};
191	
192	    const excludedIdsSet = new Set<string>(manualExcludedIds);
193	
194	    // 1. Identify creatures exceeding max limit & track owned species
195	    const ownedSpeciesSet = new Set<string>();
196	    for (const dino of objects) {
197	        const uuid = dino.uuid || dino.id || dino.name;
198	        const maxLimit = calcDinoMaxCapacity(dino);
199	        const userCount = Number(ownedDinos[uuid]?.number || 0);
200	
201	        if (userCount >= maxLimit) {
202	            excludedIdsSet.add(uuid);
203	        }
204	        if (userCount > 0) {
205	            ownedSpeciesSet.add(uuid);
206	        }
207	    }
208	
209	    // 2. Discover partner ingredients unlocked by owned species across all hybrid recipes
210	    const partnerUnlockedUuids = new Set<string>();
211	    for (const dino of objects) {
212	        const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
213	        if (rawIngredients.length >= 2) {
214	            const ingredientUuids: string[] = [];
215	            for (const ing of rawIngredients) {
216	                const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
217	                if (ingUuid) ingredientUuids.push(ingUuid);
218	            }
219	
220	            // If player owns at least one ingredient species for this hybrid recipe
221	            if (ingredientUuids.some(u => ownedSpeciesSet.has(u))) {
222	                // All partner ingredients for this hybrid recipe bypass the cap!
223	                for (const u of ingredientUuids) {
224	                    partnerUnlockedUuids.add(u);
225	                }
226	            }
227	        }
228	    }
229	
230	    // 3. Filter eligible creatures & search for Next Unlock Milestone
231	    const eligibleList: any[] = [];
232	    const lockedAboveCapList: any[] = [];
233	
234	    for (const dino of objects) {
235	        const uuid = dino.uuid || dino.id || dino.name;
236	        if (excludedIdsSet.has(uuid)) continue;
237	
238	        const evolutions = dino.evolutions || [];
239	        if (evolutions.length === 0) continue;
240	
241	        const evo4 = evolutions[3] || evolutions[evolutions.length - 1];
242	        const baseEvo4Fero = Number(
243	            dino.evo4_ferocity ||
244	            evo4.ferocity ||
245	            Math.floor(Number(evo4.damage || 0) + (Number(evo4.health || 0) / 3.2))
246	        );
247	
248	        // Extract ingredients and count owned materials
249	        const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
250	        let ownedIngredientsCount = 0;
251	        const ingredientUuids: string[] = [];
252	        for (const ing of rawIngredients) {
253	            const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
254	            if (ingUuid) {
255	                ingredientUuids.push(ingUuid);
256	                ownedIngredientsCount += Number(ownedDinos[ingUuid]?.number || 0);
257	            }
258	        }
259	
260	        const hybridType = String(dino.hybrid_type || '').toLowerCase();
261	        const isHybridWithIngredients = (hybridType === 'hybrid' || hybridType === 'super-hybrid') && ingredientUuids.length > 0;
262	
263	        // Cap bypass conditions:
264	        const isPartnerUnlock = partnerUnlockedUuids.has(uuid) && baseEvo4Fero > cap;
265	        const isHybridBypass = isHybridWithIngredients && ownedIngredientsCount > 0 && baseEvo4Fero > cap;
266	
267	        if (baseEvo4Fero <= cap || isPartnerUnlock || isHybridBypass) {
268	            eligibleList.push({
269	                dino,
270	                uuid,
271	                evolutions,
272	                evo4,
273	                baseEvo4Fero,
274	                ingredientUuids,
275	                ownedIngredientsCount,
276	                hasIngredients: isHybridWithIngredients,
277	                isPartnerUnlock,
278	                isHybridBypass,
279	            });
280	        } else {
281	            lockedAboveCapList.push({
282	                uuid,
283	                name: dino.name || '',
284	                rarity: String(dino.rarity || '').toLowerCase(),
285	                class: dino.class,
286	                image_url: dino.image_url,
287	                requiredFerocity: baseEvo4Fero,
288	                deltaNeeded: Math.max(1, Math.ceil(baseEvo4Fero * 2.5) - top3Ferocity),
289	            });
290	        }
291	    }
292	
293	    // Calculate Next Unlock Milestone
294	    lockedAboveCapList.sort((a, b) => a.requiredFerocity - b.requiredFerocity || a.name.localeCompare(b.name));
295	    const nextUnlock: NextUnlockMilestone | null = lockedAboveCapList.length > 0 ? lockedAboveCapList[0] : null;
296	
297	    if (eligibleList.length === 0) {
298	        return {
299	            pool: [],
300	            cap,
301	            top3Ferocity,
302	            totalAllFerocity,
303	            top3Dinos,
304	            topDinos,
305	            nextUnlock,
306	            totalModifiedFerocity: 0,
307	            excludedIds: Array.from(excludedIdsSet),
308	        };
309	    }
310	
311	    // 4. Compute dynamic weights:
312	    // Base weight from ferocity (inverse ferocity principle):
313	    // normal_chance_with_that_ferocity = 1 / max(1, ferocity)
314	    // Manager's Hybrid scaling formula:
315	    // hybrid_weight = normal_weight * total_materials_owned / 10 (with low baseline floor for 0 materials)
316	    let totalInverseWeight = 0;
317	    const candidates = eligibleList.map(({
318	        dino,
319	        uuid,
320	        evolutions,
321	        evo4,
322	        baseEvo4Fero,
323	        ingredientUuids,
324	        ownedIngredientsCount,
325	        hasIngredients,
326	        isPartnerUnlock,
327	        isHybridBypass
328	    }) => {
329	        // Baseline inverse ferocity weight
330	        const baseWeight = 1 / Math.max(1, baseEvo4Fero);
331	
332	        // Manager's Hybrid scaling: normal_chance * materials / 10
333	        let rawWeight = baseWeight;
334	        let hybridMultiplier = 1;
335	        if (hasIngredients) {
336	            hybridMultiplier = Math.max(0.2, ownedIngredientsCount) / 10;
337	            rawWeight = baseWeight * hybridMultiplier;
338	        }
339	
340	        totalInverseWeight += rawWeight;
341	
342	        const userDinoData = ownedDinos[uuid] || { number: 0, rank: 0 };
343	        const ownedCount = Number(userDinoData.number || 0);
344	        const currentRank = calcDinoRank(ownedCount, evolutions.length);
345	        const maximumNumber = calcDinoMaxCapacity(dino);
346	        const maxEvo = evolutions[evolutions.length - 1] || evo4;
347	
348	        const cost = calcDinoCost(dino);
349	
350	        return {
351	            uuid,
352	            name: dino.name || '',
353	            rarity: String(dino.rarity || '').toLowerCase(),
354	            class: dino.class,
355	            hybrid_type: dino.hybrid_type,
356	            ferocity: baseEvo4Fero,
357	            modifiedFerocity: baseEvo4Fero,
358	            hybridMultiplier,
359	            isPartnerUnlock: Boolean(isPartnerUnlock),
360	            isHybridBypass: Boolean(isHybridBypass),
361	            rawWeight,
362	            dropRatePercent: 0,
363	            maxDamage: Number(maxEvo.damage || 0),
364	            maxHealth: Number(maxEvo.health || 0),
365	            maxEvoImg: getDinoAvatarUrl(dino, evolutions.length, false),
366	            evo1Img: getDinoAvatarUrl(dino, 1, false),
367	            isOwned: ownedCount > 0,
368	            ownedCount,
369	            currentRank,
370	            maximumNumber,
371	            image_url: dino.image_url,
372	            hatch_time_mins: dino.hatch_time_mins,
373	            buy_price_dna: dino.buy_price_dna,
374	            sell_price_dna: dino.sell_price_dna,
375	            ingredients: ingredientUuids,
376	            ownedIngredientsCount,
377	            totalIngredientsCount: ingredientUuids.length,
378	            cost,
379	        };
380	    });
381	
382	    // 4. Calculate percentage drop rates:
383	    for (const item of candidates) {
384	        item.dropRatePercent = totalInverseWeight > 0
385	            ? (item.rawWeight / totalInverseWeight) * 100
386	            : 100 / candidates.length;
387	    }
388	
389	    // Sort descending by base ferocity, then by name
390	    candidates.sort((a, b) => b.ferocity - a.ferocity || a.name.localeCompare(b.name));
391	
392	    return {
393	        pool: candidates,
394	        cap,
395	        top3Ferocity,
396	        totalAllFerocity,
397	        top3Dinos,
398	        topDinos,
399	        nextUnlock,
400	        totalModifiedFerocity: totalInverseWeight,
401	        excludedIds: Array.from(excludedIdsSet),
402	    };
403	}
404	
405	/**
406	 * Selects a creature from the pool using dynamic weighted random selection.
407	 */
408	export function selectWeightedRoll(pool: PoolDino[]): PoolDino | null {
409	    if (!pool || pool.length === 0) return null;
410	    if (pool.length === 1) return pool[0];
411	
412	    const totalWeight = pool.reduce((sum, item) => sum + item.rawWeight, 0);
413	    let randomVal = Math.random() * totalWeight;
414	
415	    for (const item of pool) {
416	        if (randomVal < item.rawWeight) {
417	            return item;
418	        }
419	        randomVal -= item.rawWeight;
420	    }
421	
422	    return pool[pool.length - 1];
423	}
424

