    isPartnerUnlock?: boolean; // Unlocked by owning a partner ingredient, bypassing cap
    isHybridBypass?: boolean; // Hybrid unlocked by owning its material ingredients, bypassing cap
    dropRatePercent: number; // Dynamic calculated drop probability (%)
    rawWeight: number; // Internal normalized inverse weight
    maxDamage: number;
    maxHealth: number;
    maxEvoImg: string;
    evo1Img: string;
    isOwned: boolean;
    ownedCount: number;
    currentRank: number;
    maximumNumber: number;
    image_url?: string;
    hatch_time_mins?: number;
    buy_price_dna?: number;
    sell_price_dna?: number;
    ingredients: string[];
    ownedIngredientsCount: number;
    totalIngredientsCount: number;
    cost: DinoCostResult;
}

export interface TopDinoInfo {
    uuid: string;
    name: string;
    rarity: string;
    class?: string;
    rank: number;
    level: number;
    ownedCount: number;
    ferocity: number;
    damage: number;
