    image_url?: string;
}

export interface NextUnlockMilestone {
    uuid: string;
    name: string;
    rarity: string;
    class?: string;
    image_url?: string;
    requiredFerocity: number;
    deltaNeeded: number;
}

export interface GachaPoolResult {
    pool: PoolDino[];
    cap: number;
    top3Ferocity: number;
    totalAllFerocity: number;
    top3Dinos: TopDinoInfo[];
    topDinos: TopDinoInfo[];
    nextUnlock: NextUnlockMilestone | null;
    totalModifiedFerocity: number;
    excludedIds: string[];
}

/**
 * Retrieves full data on the user's top highest-ferocity active dinos (up to limit, default 25).
 */
export function getUserTopDinos(objects: any[], userProgress: any, limit: number = 25): TopDinoInfo[] {
    const ownedDinos = userProgress?.owned_dinos || {};
    const list: TopDinoInfo[] = [];

    for (const [uuid, data] of Object.entries(ownedDinos)) {
        const ownedData = data as { number?: number; rank?: number; ferocity?: number };
        const number = Number(ownedData.number || 0);

        if (number > 0) {
            const dino = objects.find((d: any) => (d.uuid || d.id || d.name) === uuid);
            if (dino && dino.evolutions?.length > 0) {
                const rank = calcDinoRank(number, dino.evolutions.length);
                if (rank > 0) {
                    const activeIndex = Math.min(rank - 1, dino.evolutions.length - 1);
                    const evo = dino.evolutions[activeIndex];
                    if (evo) {
                        const fero = evo.ferocity !== undefined
                            ? Number(evo.ferocity)
                            : Math.floor(Number(evo.damage || 0) + (Number(evo.health || 0) / 3.2));
                        const targetLevel = Number(evo.level || rank * 10);
                        list.push({
                            uuid,
                            name: dino.name || '',
                            rarity: String(dino.rarity || '').toLowerCase(),
                            class: dino.class,
                            rank,
                            level: targetLevel,
                            ownedCount: number,
                            ferocity: fero,
                            damage: Number(evo.damage || 0),
                            health: Number(evo.health || 0),
                            evoImg: getDinoAvatarUrl(dino, rank, false),
                            image_url: dino.image_url,
                        });
                    }
                }
            }
        }
    }

    list.sort((a, b) => b.ferocity - a.ferocity || a.name.localeCompare(b.name));
    return list.slice(0, limit);
}

/**
 * Retrieves full data on the user's top 3 highest-ferocity active dinos.
 */
export function getUserTop3Dinos(objects: any[], userProgress: any): TopDinoInfo[] {
    return getUserTopDinos(objects, userProgress, 3);
}

/**
 * Calculates user's top 3 ferocity sum based on highest active evolutions of owned creatures.
 */
export function calcUserTop3Ferocity(objects: any[], userProgress: any): number {
    const top3 = getUserTop3Dinos(objects, userProgress);
    return top3.reduce((sum, d) => sum + d.ferocity, 0);
}

/**
 * Calculates user's total cumulative ferocity across ALL owned dinosaurs at their active unlocked levels.
 */
export function calcUserTotalFerocity(objects: any[], userProgress: any): number {
    const ownedDinos = userProgress?.owned_dinos || {};
    let total = 0;

    for (const [uuid, data] of Object.entries(ownedDinos)) {
        const ownedData = data as { number?: number; rank?: number; ferocity?: number };
        const number = Number(ownedData.number || 0);

        if (number > 0) {
            const dino = objects.find((d: any) => (d.uuid || d.id || d.name) === uuid);
            if (dino && dino.evolutions?.length > 0) {
                const rank = calcDinoRank(number, dino.evolutions.length);
                if (rank > 0) {
                    const activeIndex = Math.min(rank - 1, dino.evolutions.length - 1);
                    const evo = dino.evolutions[activeIndex];
                    if (evo) {
                        const fero = evo.ferocity !== undefined
                            ? Number(evo.ferocity)
                            : Math.floor(Number(evo.damage || 0) + (Number(evo.health || 0) / 3.2));
                        total += fero;
                    }
                }
            }
        }
    }

    return total;
}

/**
 * Main Gacha Pool Generator:
 * 1. Gates creatures by evo4_ferocity <= cap, where cap = max(floor(top3Ferocity / 2.5), 200).
 * 2. Excludes creatures that reached maximum_number.
 * 3. Applies ingredient scaling: hybrid_weight = normal_weight * (materials / 10).
 * 4. Partner & Hybrid bypass: Partner ingredient dinosaurs and Hybrids with owned materials bypass the cap.
 * 5. Calculates true inverse ferocity drop rates: w_i = 1 / ferocity (least ferocity -> highest drop rate).
 * 6. Finds the Next Unlock Milestone (the creature with lowest ferocity just above cap).
 * 7. Computes Top 3 Vanguards and Total Army Ferocity.
 */
export function calcGachaPool(
    objects: any[],
    userProgress: any,
    manualExcludedIds: string[] = []
): GachaPoolResult {
    const topDinos = getUserTopDinos(objects, userProgress, 25);
    const top3Dinos = topDinos.slice(0, 3);
    const top3Ferocity = top3Dinos.reduce((sum, d) => sum + d.ferocity, 0);
    const totalAllFerocity = calcUserTotalFerocity(objects, userProgress);
    // Cap is top 3 ferocity divided by 2.5, with minimum baseline floor of 200
    const cap = Math.max(Math.floor(top3Ferocity / 2.5), 200);
    const ownedDinos = userProgress?.owned_dinos || {};

    const excludedIdsSet = new Set<string>(manualExcludedIds);

    // 1. Identify creatures exceeding max limit & track owned species
    const ownedSpeciesSet = new Set<string>();
    for (const dino of objects) {
        const uuid = dino.uuid || dino.id || dino.name;
        const maxLimit = calcDinoMaxCapacity(dino);
        const userCount = Number(ownedDinos[uuid]?.number || 0);

        if (userCount >= maxLimit) {
            excludedIdsSet.add(uuid);
        }
        if (userCount > 0) {
            ownedSpeciesSet.add(uuid);
        }
    }

    // 2. Discover partner ingredients unlocked by owned species across all hybrid recipes
    const partnerUnlockedUuids = new Set<string>();
    for (const dino of objects) {
        const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
        if (rawIngredients.length >= 2) {
            const ingredientUuids: string[] = [];
            for (const ing of rawIngredients) {
                const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
                if (ingUuid) ingredientUuids.push(ingUuid);
            }

            // If player owns at least one ingredient species for this hybrid recipe
            if (ingredientUuids.some(u => ownedSpeciesSet.has(u))) {
                // All partner ingredients for this hybrid recipe bypass the cap!
                for (const u of ingredientUuids) {
                    partnerUnlockedUuids.add(u);
                }
            }
        }
    }

    // 3. Filter eligible creatures & search for Next Unlock Milestone
    const eligibleList: any[] = [];
    const lockedAboveCapList: any[] = [];

    for (const dino of objects) {
        const uuid = dino.uuid || dino.id || dino.name;
        if (excludedIdsSet.has(uuid)) continue;

        const evolutions = dino.evolutions || [];
        if (evolutions.length === 0) continue;

        const evo4 = evolutions[3] || evolutions[evolutions.length - 1];
        const baseEvo4Fero = Number(
            dino.evo4_ferocity ||
            evo4.ferocity ||
            Math.floor(Number(evo4.damage || 0) + (Number(evo4.health || 0) / 3.2))
        );

        // Extract ingredients and count owned materials
        const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
        let ownedIngredientsCount = 0;
        const ingredientUuids: string[] = [];
        for (const ing of rawIngredients) {
            const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
            if (ingUuid) {
                ingredientUuids.push(ingUuid);
                ownedIngredientsCount += Number(ownedDinos[ingUuid]?.number || 0);
            }
        }

        const hybridType = String(dino.hybrid_type || '').toLowerCase();
        const isHybridWithIngredients = (hybridType === 'hybrid' || hybridType === 'super-hybrid') && ingredientUuids.length > 0;

        // Cap bypass conditions:
        const isPartnerUnlock = partnerUnlockedUuids.has(uuid) && baseEvo4Fero > cap;
        const isHybridBypass = isHybridWithIngredients && ownedIngredientsCount > 0 && baseEvo4Fero > cap;

        if (baseEvo4Fero <= cap || isPartnerUnlock || isHybridBypass) {
            eligibleList.push({
                dino,
                uuid,
                evolutions,
                evo4,
                baseEvo4Fero,
                ingredientUuids,
                ownedIngredientsCount,
                hasIngredients: isHybridWithIngredients,
                isPartnerUnlock,
                isHybridBypass,
            });
        } else {
            lockedAboveCapList.push({
                uuid,
                name: dino.name || '',
                rarity: String(dino.rarity || '').toLowerCase(),
                class: dino.class,
                image_url: dino.image_url,
                requiredFerocity: baseEvo4Fero,
                deltaNeeded: Math.max(1, Math.ceil(baseEvo4Fero * 2.5) - top3Ferocity),
            });
        }
    }

    // Calculate Next Unlock Milestone
    lockedAboveCapList.sort((a, b) => a.requiredFerocity - b.requiredFerocity || a.name.localeCompare(b.name));
    const nextUnlock: NextUnlockMilestone | null = lockedAboveCapList.length > 0 ? lockedAboveCapList[0] : null;

    if (eligibleList.length === 0) {
        return {
            pool: [],
            cap,
            top3Ferocity,
            totalAllFerocity,
            top3Dinos,
            topDinos,
            nextUnlock,
            totalModifiedFerocity: 0,
            excludedIds: Array.from(excludedIdsSet),
        };
    }

    // 4. Compute dynamic weights:
    // Base weight from ferocity (inverse ferocity principle):
    // normal_chance_with_that_ferocity = 1 / max(1, ferocity)
    // Manager's Hybrid scaling formula:
    // hybrid_weight = normal_weight * total_materials_owned / 10 (with low baseline floor for 0 materials)
    let totalInverseWeight = 0;
    const candidates = eligibleList.map(({
        dino,
        uuid,
        evolutions,
        evo4,
        baseEvo4Fero,
        ingredientUuids,
        ownedIngredientsCount,
        hasIngredients,
        isPartnerUnlock,
        isHybridBypass
    }) => {
        // Baseline inverse ferocity weight
        const baseWeight = 1 / Math.max(1, baseEvo4Fero);

        // Manager's Hybrid scaling: normal_chance * materials / 10
        let rawWeight = baseWeight;
        let hybridMultiplier = 1;
        if (hasIngredients) {
            hybridMultiplier = Math.max(0.2, ownedIngredientsCount) / 10;
            rawWeight = baseWeight * hybridMultiplier;
        }

        totalInverseWeight += rawWeight;

        const userDinoData = ownedDinos[uuid] || { number: 0, rank: 0 };
        const ownedCount = Number(userDinoData.number || 0);
        const currentRank = calcDinoRank(ownedCount, evolutions.length);
        const maximumNumber = calcDinoMaxCapacity(dino);
        const maxEvo = evolutions[evolutions.length - 1] || evo4;

        const cost = calcDinoCost(dino);

        return {
            uuid,
            name: dino.name || '',
            rarity: String(dino.rarity || '').toLowerCase(),
            class: dino.class,
            hybrid_type: dino.hybrid_type,
            ferocity: baseEvo4Fero,
            modifiedFerocity: baseEvo4Fero,
            hybridMultiplier,
            isPartnerUnlock: Boolean(isPartnerUnlock),
            isHybridBypass: Boolean(isHybridBypass),
            rawWeight,
            dropRatePercent: 0,
            maxDamage: Number(maxEvo.damage || 0),
            maxHealth: Number(maxEvo.health || 0),
            maxEvoImg: getDinoAvatarUrl(dino, evolutions.length, false),
            evo1Img: getDinoAvatarUrl(dino, 1, false),
            isOwned: ownedCount > 0,
            ownedCount,
            currentRank,
            maximumNumber,
            image_url: dino.image_url,
            hatch_time_mins: dino.hatch_time_mins,
            buy_price_dna: dino.buy_price_dna,
            sell_price_dna: dino.sell_price_dna,
            ingredients: ingredientUuids,
            ownedIngredientsCount,
            totalIngredientsCount: ingredientUuids.length,
            cost,
        };
    });

    // 4. Calculate percentage drop rates:
    for (const item of candidates) {
        item.dropRatePercent = totalInverseWeight > 0
            ? (item.rawWeight / totalInverseWeight) * 100
            : 100 / candidates.length;
    }

    // Sort descending by base ferocity, then by name
    candidates.sort((a, b) => b.ferocity - a.ferocity || a.name.localeCompare(b.name));

    return {
        pool: candidates,
        cap,
        top3Ferocity,
        totalAllFerocity,
        top3Dinos,
        topDinos,
        nextUnlock,
        totalModifiedFerocity: totalInverseWeight,
        excludedIds: Array.from(excludedIdsSet),
    };
}

/**
 * Selects a creature from the pool using dynamic weighted random selection.
 */
export function selectWeightedRoll(pool: PoolDino[]): PoolDino | null {
    if (!pool || pool.length === 0) return null;
    if (pool.length === 1) return pool[0];

    const totalWeight = pool.reduce((sum, item) => sum + item.rawWeight, 0);
    let randomVal = Math.random() * totalWeight;

    for (const item of pool) {
        if (randomVal < item.rawWeight) {
            return item;
        }
        randomVal -= item.rawWeight;
    }

    return pool[pool.length - 1];
}

