          wagerOption = [1, 2, 3, 4, 8, 16].includes(parsed) ? parsed : 1;
        }
      } catch {
        wagerOption = 1;
      }

      const roll = selectWeightedRoll(possibleOutcomes);
      if (!roll) return;
      targetUuid = roll.uuid;

      const dinoObj = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
      if (wagerOption === 'next-evo') {
        multiplier = calcDinosNeededForDinoNextEvo(dinoObj || roll, userProgress);
      } else if (wagerOption === 'max-evo') {
        multiplier = calcDinosNeededForDinoMaxEvo(dinoObj || roll, userProgress);
      } else {
        const num = typeof wagerOption === 'number' ? wagerOption : Number(wagerOption);
        multiplier = isNaN(num) || num < 1 ? 1 : num;
      }
    }

    const dino = objects.find(o => (o.uuid || (o as any).id || (o as any).name) === targetUuid);
    if (!dino) return;

    // 3. Affordability & Capacity Check
    const cost = calcDinoCost(dino);
    const currentData = userProgress?.owned_dinos?.[targetUuid] || { number: 0, rank: 0 };
    const currentCount = Number((currentData as any).number || 0);
    const maxCapacity = calcDinoMaxCapacity(dino);
    const maxBuyable = Math.max(1, maxCapacity - currentCount);
    const buyQty = Math.min(Math.max(1, multiplier), maxBuyable);

    const totalTimeSeconds = cost.totalTimeSeconds * buyQty;

    let canAfford = isFreeBuyCheat;
    if (!canAfford) {
      const currentJurassicTime = Number(myResources.jurassic_time?.amount ?? myResources.elemental_time?.golden?.amount ?? 0);
      canAfford = currentJurassicTime >= totalTimeSeconds;
    }

    if (!canAfford) {
      // If cannot afford, save as due dino if not already set, and wait for resources
      if (!dueDino) {
        handleSetDueDino({
          uuid: targetUuid,
          multiplier
        });
      }
      return;
    }

    // 4. Deduct resources if cheat disabled
    if (!isFreeBuyCheat) {
      const newRes = { ...myResources };
      const currentJurassicTime = Number(newRes.jurassic_time?.amount ?? newRes.elemental_time?.golden?.amount ?? 0);

      newRes.jurassic_time = {
        ...newRes.jurassic_time,
        amount: Math.max(0, Number((currentJurassicTime - totalTimeSeconds).toFixed(2)))
      };

      handleUpdateResources(newRes);
    }

    // 5. Calculate pool differential and extract target pool drop rate
    const prevPoolResult = calcGachaPool(objects, userProgress, excludedIds);
    const prevPoolSet = new Set(prevPoolResult.pool.map(p => p.uuid));
    const prevCap = prevPoolResult.cap;
    const targetPoolDino = prevPoolResult.pool.find(p => p.uuid === targetUuid);
    const dropRatePercent = targetPoolDino ? targetPoolDino.dropRatePercent : undefined;

    // 6. Update progress & rank
    const newProg = { ...userProgress, owned_dinos: { ...(userProgress?.owned_dinos || {}) } };
    const updatedCount = currentCount + buyQty;
    const evoCount = dino.evolutions?.length || 4;
    const prevRank = calcDinoRank(currentCount, evoCount);
    const newRank = calcDinoRank(updatedCount, evoCount);
    const wasFirstBuy = currentCount === 0;

    newProg.owned_dinos[targetUuid] = {
      number: updatedCount,
      rank: newRank
    };

    handleUpdateProgress(newProg);

    // Post-progress pool
    const postPoolResult = calcGachaPool(objects, newProg, excludedIds);
    const newCap = postPoolResult.cap;
    const newlyUnlockedPoolDinos = postPoolResult.pool.filter(p => !prevPoolSet.has(p.uuid));

    // Clear due dino on successful purchase
    if (dueDino) {
      handleSetDueDino(null);
    }

    // 7. Trigger Rank Climb animation directly on active view
    setBuyAnimationTarget({
      uuid: targetUuid,
      wasFirstBuy,
      prevRank,
      newRank,
      buyQty,
      dropRatePercent,
      newlyUnlockedPoolDinos,
      prevCap,
      newCap
    });

    // 8. Decrement remaining auto rolls (shutdown will be triggered AFTER up-evo / rank climb finishes)
    const nextRolls = Math.max(0, autoRollsRemainingRef.current - 1);
    autoRollsRemainingRef.current = nextRolls;
    setAutoRollsRemaining(nextRolls);

    // Ensure view is on List of Dinos so the user experiences the rank climb animation
    if (view !== 'alldinos') {
      setView('alldinos');
    }
  };

  timer = setTimeout(executeAutonomousStep, 600);

  return () => {
    if (timer) clearTimeout(timer);
  };
}, [
  isAutoGachaBuy,
  loading,
  buyAnimationTarget,
  rosterTargetUuid,
  objects,
  userProgress,
  excludedIds,
  dueDino,
  isFreeBuyCheat,
  myResources,
  view
]);

